def _numen_huella(im):
    """pHash DCT de 64 bits; no depende de los metadatos ni del JPEG."""
    import numpy as np
    from PIL import Image
    a=np.asarray(im.convert('L').resize((32,32),Image.Resampling.LANCZOS),dtype=np.float64)
    k=np.arange(8)[:,None]; j=np.arange(32)[None,:]
    b=np.cos(np.pi*(j+.5)*k/32); v=(b@a@b.T).ravel()
    bits=v>np.median(v[1:]);bits[0]=False
    return f'{sum(int(x)<<i for i,x in enumerate(bits)):016x}'


def _numen_distancia(a,b):
    return (int(a,16)^int(b,16)).bit_count()


def _numen_transformar_capa(img_rgba, mask_l, perfil, rng):
    """Aplica variaciones de pose/encuadre manteniendo a la misma androide."""
    from PIL import Image, ImageFilter
    W,H=img_rgba.size
    scale=max(0.84,min(1.32,float(perfil.get('scale',1.0))*float(rng.uniform(0.97,1.03))))
    nw,nh=max(1,int(W*scale)),max(1,int(H*scale))
    img=img_rgba.resize((nw,nh),Image.Resampling.LANCZOS)
    mask=mask_l.resize((nw,nh),Image.Resampling.LANCZOS)
    img=img.copy(); img.putalpha(mask)
    dx=int(perfil.get('dx',0)+rng.integers(-20,21))
    dy=int(perfil.get('dy',0)+rng.integers(-14,15))
    ang=float(perfil.get('angle',0.0))+float(rng.uniform(-1.0,1.0))
    shear=float(perfil.get('shear',0.0))+float(rng.uniform(-0.012,0.012))
    capa=Image.new('RGBA',(W,H),(0,0,0,0))
    capa_mask=Image.new('L',(W,H),0)
    x=(W-nw)//2+dx; y=(H-nh)//2+dy
    capa.paste(img,(x,y),img if img.mode=='RGBA' else None)
    capa_mask.paste(mask,(x,y))
    if abs(shear)>.003:
        tx=-shear*H*.45
        matrix=(1.0,shear,tx,0.0,1.0,0.0)
        capa=capa.transform((W,H),Image.AFFINE,matrix,resample=Image.Resampling.BICUBIC,fillcolor=(0,0,0,0))
        capa_mask=capa_mask.transform((W,H),Image.AFFINE,matrix,resample=Image.Resampling.BICUBIC,fillcolor=0)
    if abs(ang)>.08:
        capa=capa.rotate(ang,resample=Image.Resampling.BICUBIC,expand=False,fillcolor=(0,0,0,0))
        capa_mask=capa_mask.rotate(ang,resample=Image.Resampling.BICUBIC,expand=False,fillcolor=0)
    blur=max(4.0,min(9.0,5.0+abs(ang)*.18+abs(shear)*25))
    return capa,capa_mask.filter(ImageFilter.GaussianBlur(blur))


def _numen_halo_y_particulas(base_rgba, mask_l, perfil, rng, paleta):
    from PIL import Image, ImageDraw, ImageFilter
    W,H=base_rgba.size
    bbox=mask_l.getbbox()
    if not bbox:
        return base_rgba
    x0,y0,x1,y1=bbox
    cx=(x0+x1)//2+int(perfil.get('halo_dx',0))
    cy=y0+int((y1-y0)*0.26)+int(perfil.get('halo_dy',0))
    radio=int(max(120,min(420,(y1-y0)*0.32*float(perfil.get('halo_scale',1.0)))))
    halo=Image.new('RGBA',(W,H),(0,0,0,0))
    d=ImageDraw.Draw(halo)
    oro=tuple(int(c) for c in paleta[2]); cian=tuple(int(c) for c in paleta[1])
    for extra,alpha,col in ((radio,70,oro),(int(radio*0.72),110,cian),(int(radio*0.46),135,oro)):
        d.ellipse((cx-extra,cy-extra,cx+extra,cy+extra),outline=col+(alpha,),width=max(2,int(extra*0.04)))
    halo=halo.filter(ImageFilter.GaussianBlur(max(8,int(radio*0.08))))
    # Niebla suave alrededor del pecho y hombros.
    mist=Image.new('RGBA',(W,H),(0,0,0,0)); dm=ImageDraw.Draw(mist)
    mx0=max(0,x0-int((x1-x0)*0.10)); mx1=min(W,x1+int((x1-x0)*0.10))
    my0=max(0,y0+int((y1-y0)*0.24)); my1=min(H,y1+int((y1-y0)*0.92))
    alpha_m=int(255*float(perfil.get('mist',0.1)))
    dm.ellipse((mx0,my0,mx1,my1),fill=oro+(alpha_m,))
    mist=mist.filter(ImageFilter.GaussianBlur(46))
    # Partículas pequeñas alrededor de la silueta.
    parts=Image.new('RGBA',(W,H),(0,0,0,0)); dp=ImageDraw.Draw(parts)
    for _ in range(int(rng.integers(30,65))):
        px=int(rng.integers(max(0,x0-140),min(W,x1+140)))
        py=int(rng.integers(max(0,y0-120),min(H,y1+140)))
        rr=float(rng.uniform(0.8,3.4)); col=oro if rng.random()<0.62 else cian
        dp.ellipse((px-rr,py-rr,px+rr,py+rr),fill=col+(int(rng.integers(55,145)),))
    parts=parts.filter(ImageFilter.GaussianBlur(0.55))
    out=Image.alpha_composite(base_rgba,halo)
    out=Image.alpha_composite(out,mist)
    out=Image.alpha_composite(out,parts)
    return out


def _numen_composicion_v1(seed, indice, devolver_fondo=False):
    """Nuevo universo procedural: nubes multiescala, galaxia, planetas y estrellas.
    Conserva el androide original como sujeto recurrente; no es un modelo de difusión.
    """
    import base64, io
    import numpy as np
    from PIL import Image, ImageDraw, ImageFilter, ImageEnhance, ImageOps
    rng=np.random.default_rng(seed)
    W,H=960,540
    yy,xx=np.mgrid[0:H,0:W].astype(np.float32)
    X=(xx-W/2)/H;Y=(yy-H/2)/H
    def nube():
        n=np.zeros((H,W),np.float32)
        for tam,amp in [(5,1.),(11,.64),(23,.38),(53,.19),(109,.10),(227,.045)]:
            z=rng.integers(0,256,(tam,round(tam*W/H)),dtype=np.uint8)
            n+=amp*np.asarray(Image.fromarray(z).resize((W,H),Image.Resampling.BICUBIC),dtype=np.float32)/255
        return (n-n.min())/max(float(n.max()-n.min()),1e-6)
    a,b=nube(),nube()
    paletas=[((103,28,200),(18,143,250),(255,157,55)),((16,92,212),(34,216,211),(255,198,90)),((189,28,117),(76,39,217),(255,170,70)),((35,137,99),(27,88,198),(239,218,122)),((176,49,20),(126,27,164),(255,194,71)),((42,41,173),(207,69,220),(255,220,150)),((12,128,151),(96,30,167),(255,170,100)),((122,27,58),(32,58,180),(255,209,111))]
    p=np.asarray(paletas[int(rng.integers(len(paletas)))],dtype=np.float32)/255
    cx,cy=rng.uniform(-.82,.82),rng.uniform(-.4,.4)
    ang=rng.uniform(0,2*np.pi); u=(X-cx)*np.cos(ang)+(Y-cy)*np.sin(ang);v=(-(X-cx)*np.sin(ang)+(Y-cy)*np.cos(ang))*rng.uniform(1.4,3.7)
    r=np.hypot(u,v); theta=np.arctan2(v,u)
    brazo=(.5+.5*np.cos(theta*rng.choice([2,3,4]) - r*rng.uniform(9,19)+b*3))**3
    disco=np.exp(-r*rng.uniform(2.5,4.8))*brazo
    curva=Y-rng.uniform(-.25,.25)-rng.uniform(.10,.30)*np.sin(X*rng.uniform(3,7)+rng.uniform(0,6.28))
    filamento=np.exp(-np.abs(curva+(a-.5)*.45)*rng.uniform(5,12))
    polvo=np.clip((a-.20)*1.35,0,1)**2
    gas=np.clip((b-.28)*1.55,0,1)**2
    rgb=np.zeros((H,W,3),np.float32)+np.array([.013,.009,.034],np.float32)
    rgb+=(polvo*(.45+filamento*.75))[...,None]*p[0]
    rgb+=(gas*(.23+filamento*.7))[...,None]*p[1]
    rgb+=(disco*.9+np.exp(-r*19)*.95+np.maximum(0,a-.73)*filamento*1.8)[...,None]*p[2]
    rgb*=np.clip(1.08-.24*(X*X+Y*Y),.55,1.0)[...,None]
    fondo=Image.fromarray(np.uint8(np.clip(rgb,0,1)**.88*255),'RGB').convert('RGBA')
    estrellas=Image.new('RGBA',(W,H));draw=ImageDraw.Draw(estrellas)
    for _ in range(int(rng.integers(400,850))):
        x,y=int(rng.integers(W)),int(rng.integers(H));q=int(rng.integers(60,235));rr=float(rng.choice([.4,.6,.8,1.1,1.8],p=[.29,.32,.25,.11,.03]));col=(220,234,255,q)
        draw.ellipse((x-rr,y-rr,x+rr,y+rr),fill=col)
        if rr>1.5:
            draw.line((x-5,y,x+5,y),fill=(255,224,179,120));draw.line((x,y-5,x,y+5),fill=(255,224,179,120))
    fondo=Image.alpha_composite(fondo,estrellas)
    # Planeta con volumen, iluminación direccional y textura de nubes.
    for _ in range(int(rng.integers(1,4))):
        px=float(rng.choice([rng.uniform(35,210),rng.uniform(740,925)]));py=float(rng.uniform(45,405));ra=float(rng.uniform(24,94))
        dx=(xx-px)/ra;dy=(yy-py)/ra;rr=dx*dx+dy*dy;z=np.sqrt(np.maximum(0,1-rr));l=np.clip(-.66*dx-.52*dy+.55*z,0,1)
        tonos=(.11+.74*l[...,None])*p[1]+(.10+.26*a[...,None])*p[0]
        tonos*= (.55+.6*b[...,None]);tonos+=np.exp(-np.abs(rr-1)*21)[...,None]*p[2]*.30
        alpha=np.clip((1-rr)*45,0,1)
        planeta=np.dstack((np.clip(tonos,0,1), alpha));fondo=Image.alpha_composite(fondo,Image.fromarray(np.uint8(planeta*255),'RGBA'))
    fondo=fondo.convert('RGB').resize((1920,1080),Image.Resampling.LANCZOS)
    with Image.open(io.BytesIO(base64.b64decode(_NUMEN_ARTE[indice]))) as raw:
        sujeto=raw.convert('RGB').resize((1920,1080),Image.Resampling.LANCZOS)
    # Desplazar ligeramente la composición completa sin estirar el rostro.
    mask=Image.new('L',(480,270));md=ImageDraw.Draw(mask);md.polygon(_NUMEN_SILUETAS[indice],fill=255)
    mask=mask.filter(ImageFilter.GaussianBlur(5)).resize((1920,1080),Image.Resampling.LANCZOS)
    sujeto=ImageEnhance.Color(sujeto).enhance(float(rng.uniform(.90,1.13)))
    if rng.random()<.5:
        sujeto=ImageOps.mirror(sujeto);mask=ImageOps.mirror(mask)
    # Pequeña parte de la nebulosa original conserva una transición fotográfica natural.
    cosmos=fondo.copy() if devolver_fondo else None
    fondo=Image.blend(fondo,sujeto,.16)
    retrato=Image.composite(sujeto,fondo,mask)
    return (retrato,cosmos) if devolver_fondo else retrato


def _numen_composicion_v2(seed, indice, devolver_fondo=False, *, pose_id=None):
    """Universo procedural + misma androide, con pose y encuadre variables por episodio."""
    import base64, io
    import numpy as np
    from PIL import Image, ImageDraw, ImageFilter, ImageEnhance, ImageOps
    rng=np.random.default_rng(seed)
    perfil=NUMEN_POSES_CONTEMPLATIVAS[(seed//len(_NUMEN_ARTE))%len(NUMEN_POSES_CONTEMPLATIVAS) if pose_id is None else int(pose_id)%len(NUMEN_POSES_CONTEMPLATIVAS)]
    W,H=960,540
    yy,xx=np.mgrid[0:H,0:W].astype(np.float32)
    X=(xx-W/2)/H;Y=(yy-H/2)/H
    def nube():
        n=np.zeros((H,W),np.float32)
        for tam,amp in [(5,1.),(11,.64),(23,.38),(53,.19),(109,.10),(227,.045)]:
            z=rng.integers(0,256,(tam,round(tam*W/H)),dtype=np.uint8)
            n+=amp*np.asarray(Image.fromarray(z).resize((W,H),Image.Resampling.BICUBIC),dtype=np.float32)/255
        return (n-n.min())/max(float(n.max()-n.min()),1e-6)
    a,b=nube(),nube()
    paletas=[((103,28,200),(18,143,250),(255,157,55)),((16,92,212),(34,216,211),(255,198,90)),((189,28,117),(76,39,217),(255,170,70)),((35,137,99),(27,88,198),(239,218,122)),((176,49,20),(126,27,164),(255,194,71)),((42,41,173),(207,69,220),(255,220,150)),((12,128,151),(96,30,167),(255,170,100)),((122,27,58),(32,58,180),(255,209,111))]
    paleta=paletas[int(rng.integers(len(paletas)))]
    p=np.asarray(paleta,dtype=np.float32)/255
    cx,cy=rng.uniform(-.82,.82),rng.uniform(-.4,.4)
    ang=rng.uniform(0,2*np.pi); u=(X-cx)*np.cos(ang)+(Y-cy)*np.sin(ang);v=(-(X-cx)*np.sin(ang)+(Y-cy)*np.cos(ang))*rng.uniform(1.4,3.7)
    r=np.hypot(u,v); theta=np.arctan2(v,u)
    brazo=(.5+.5*np.cos(theta*rng.choice([2,3,4]) - r*rng.uniform(9,19)+b*3))**3
    disco=np.exp(-r*rng.uniform(2.5,4.8))*brazo
    curva=Y-rng.uniform(-.25,.25)-rng.uniform(.10,.30)*np.sin(X*rng.uniform(3,7)+rng.uniform(0,6.28))
    filamento=np.exp(-np.abs(curva+(a-.5)*.45)*rng.uniform(5,12))
    polvo=np.clip((a-.20)*1.35,0,1)**2
    gas=np.clip((b-.28)*1.55,0,1)**2
    rgb=np.zeros((H,W,3),np.float32)+np.array([.013,.009,.034],np.float32)
    rgb+=(polvo*(.45+filamento*.75))[...,None]*p[0]
    rgb+=(gas*(.23+filamento*.7))[...,None]*p[1]
    rgb+=(disco*.9+np.exp(-r*19)*.95+np.maximum(0,a-.73)*filamento*1.8)[...,None]*p[2]
    rgb*=np.clip(1.08-.24*(X*X+Y*Y),.55,1.0)[...,None]
    fondo=Image.fromarray(np.uint8(np.clip(rgb,0,1)**.88*255),'RGB').convert('RGBA')
    estrellas=Image.new('RGBA',(W,H));draw=ImageDraw.Draw(estrellas)
    for _ in range(int(rng.integers(400,850))):
        x,y=int(rng.integers(W)),int(rng.integers(H));q=int(rng.integers(60,235));rr=float(rng.choice([.4,.6,.8,1.1,1.8],p=[.29,.32,.25,.11,.03]));col=(220,234,255,q)
        draw.ellipse((x-rr,y-rr,x+rr,y+rr),fill=col)
        if rr>1.5:
            draw.line((x-5,y,x+5,y),fill=(255,224,179,120));draw.line((x,y-5,x,y+5),fill=(255,224,179,120))
    fondo=Image.alpha_composite(fondo,estrellas)
    # Planetas y brillos secundarios.
    for _ in range(int(rng.integers(1,4))):
        px=float(rng.choice([rng.uniform(35,210),rng.uniform(740,925)]));py=float(rng.uniform(45,405));ra=float(rng.uniform(24,94))
        dx=(xx-px)/ra;dy=(yy-py)/ra;rr=dx*dx+dy*dy;z=np.sqrt(np.maximum(0,1-rr));l=np.clip(-.66*dx-.52*dy+.55*z,0,1)
        tonos=(.11+.74*l[...,None])*p[1]+(.10+.26*a[...,None])*p[0]
        tonos*= (.55+.6*b[...,None]);tonos+=np.exp(-np.abs(rr-1)*21)[...,None]*p[2]*.30
        alpha=np.clip((1-rr)*45,0,1)
        planeta=np.dstack((np.clip(tonos,0,1), alpha));fondo=Image.alpha_composite(fondo,Image.fromarray(np.uint8(planeta*255),'RGBA'))
    fondo=fondo.convert('RGB').resize((1920,1080),Image.Resampling.LANCZOS)
    with Image.open(io.BytesIO(base64.b64decode(_NUMEN_ARTE[indice]))) as raw:
        sujeto=raw.convert('RGB').resize((1920,1080),Image.Resampling.LANCZOS)
    mask=Image.new('L',(480,270));md=ImageDraw.Draw(mask);md.polygon(_NUMEN_SILUETAS[indice],fill=255)
    mask=mask.filter(ImageFilter.GaussianBlur(5)).resize((1920,1080),Image.Resampling.LANCZOS)
    sujeto=ImageEnhance.Color(sujeto).enhance(float(rng.uniform(.92,1.12)))
    sujeto=ImageEnhance.Contrast(sujeto).enhance(float(rng.uniform(.97,1.10)))
    mir=perfil.get('mirror','auto')
    if mir is True or (mir=='auto' and rng.random()<.5):
        sujeto=ImageOps.mirror(sujeto);mask=ImageOps.mirror(mask)
    sujeto_rgba=sujeto.convert('RGBA')
    sujeto_rgba,mask=_numen_transformar_capa(sujeto_rgba,mask,perfil,rng)
    cosmos=fondo.copy() if devolver_fondo else None
    fondo_rgba=fondo.convert('RGBA')
    fondo_rgba=_numen_halo_y_particulas(fondo_rgba,mask,perfil,rng,paleta)
    mezcla=sujeto_rgba.copy(); mezcla.putalpha(mask.point(lambda p:int(p*float(perfil.get('subject_mix',0.13)))))
    fondo_rgba=Image.alpha_composite(fondo_rgba,mezcla)
    retrato=Image.alpha_composite(fondo_rgba,sujeto_rgba)
    # Viñeta suave para unificar la atención sobre el personaje.
    vig=Image.new('L',(1920,1080),0); dv=ImageDraw.Draw(vig)
    dv.ellipse((-180,-120,2100,1200),fill=255)
    vig=vig.filter(ImageFilter.GaussianBlur(150))
    negro=Image.new('RGBA',(1920,1080),(0,0,0,0))
    negro.putalpha(vig.point(lambda p:int((255-p)*0.34)))
    retrato=Image.alpha_composite(retrato,negro).convert('RGB')
    return (retrato,cosmos) if devolver_fondo else retrato


def _numen_fondo_pose_100(seed, indice, pose_id):
    """Retrato Full HD a partir de una de 100 posturas anatómicas pre-renderizadas.

    No depende de archivos de imagen externos, claves o servicios de pago.
    """
    import base64, io
    import numpy as np
    from PIL import Image, ImageDraw, ImageEnhance, ImageFilter
    if not (100 <= pose_id < 200):
        raise ValueError('pose_id debe estar entre 100 y 199')
    n=pose_id-100
    sheet_index, panel=divmod(n,10)
    with Image.open(io.BytesIO(base64.b64decode(''.join(_NUMEN_BANCO_100_JPEG[sheet_index])))) as sheet:
        w,h=sheet.size
        col,row=panel%5,panel//5
        x0=round(w*col/5)+4; x1=round(w*(col+1)/5)-4
        y0=round(h*row/2)+4; y1=round(h*(row+1)/2)-4
        tile=sheet.convert('RGB').crop((x0,y0,x1,y1))
    rng=np.random.default_rng(seed)
    # El fondo del propio panel ocupa toda la pantalla, desenfocado para evitar
    # un recuadro cuadrado. El sujeto original permanece nítido, sin deformación.
    W,H=1920,1080
    base=tile.resize((W,H),Image.Resampling.LANCZOS).filter(ImageFilter.GaussianBlur(43))
    base=ImageEnhance.Brightness(base).enhance(.68)
    # Imagen de primer plano: no alteramos la pose ni la anatomía de la figura.
    lado=int(rng.integers(1070,1180))
    tile=tile.resize((lado,lado),Image.Resampling.LANCZOS)
    x=(W-lado)//2+int(rng.integers(-95,96))
    y=(H-lado)//2+int(rng.integers(-45,46))
    # Máscara suavizada: fusiona ambiente y figura con márgenes atmosféricos.
    mask=Image.new('L',(lado,lado),0)
    d=ImageDraw.Draw(mask)
    margen=58
    d.rounded_rectangle((margen,margen,lado-margen,lado-margen),radius=130,fill=255)
    mask=mask.filter(ImageFilter.GaussianBlur(77))
    base.paste(tile,(x,y),mask)
    # Variaciones finas del brillo y el cielo; la pose nunca es reemplazada.
    base=ImageEnhance.Color(base).enhance(float(rng.uniform(.96,1.07)))
    return base


def _numen_composicion(seed, indice, devolver_fondo=False, *, pose_id=None):
    """Compatible con cosmos-v1/v2 y con las 100 nuevas poses reales (v3)."""
    if pose_id is not None and 100 <= int(pose_id) < 200:
        retrato=_numen_fondo_pose_100(seed,indice,int(pose_id))
        if devolver_fondo:
            # CTA sin androide, mismo universo procedural del episodio.
            _,cosmos=_numen_composicion_v2(seed,indice,devolver_fondo=True)
            return retrato,cosmos
        return retrato
    return _numen_composicion_v2(seed,indice,devolver_fondo=devolver_fondo,pose_id=pose_id)


def _ent_fotos(d, carpeta):
    """Una sola ilustración por episodio; reserva persistente antes de render/publicar."""
    import io
    from PIL import Image
    carpeta=Path(carpeta);carpeta.mkdir(parents=True,exist_ok=True)
    eid=str(d['id']);registro=_ent_read(NUMEN_REGISTRO_VISUAL,{})
    if not isinstance(registro,dict):raise EpisodioRecuperable('Registro visual inválido; restaurar respaldo.')
    for k,v in registro.items():
        if not isinstance(v,dict) or not isinstance(v.get('seed'),int) or not isinstance(v.get('indice'),int) or not 0<=v['indice']<len(_NUMEN_ARTE) or not re.fullmatch('[0-9a-f]{16}',str(v.get('phash',''))) or not re.fullmatch('[0-9a-f]{64}',str(v.get('sha256',''))):
            raise EpisodioRecuperable('Registro visual dañado: '+str(k))
        if 'pose_id' in v and (not isinstance(v.get('pose_id'),int) or not (0<=v['pose_id']<len(NUMEN_POSES_CONTEMPLATIVAS) or 100<=v['pose_id']<200)):
            raise EpisodioRecuperable('Registro visual dañado en pose: '+str(k))
    previo=registro.get(eid);otros=[v for k,v in registro.items() if k!=eid];semillas={v['seed'] for v in otros}; hashes={v['sha256'] for v in otros}
    for intento in range(1 if previo else 120):
        seed=previo['seed'] if previo else int(hashlib.sha256(f'numen-cosmos-v3:{eid}:{intento}'.encode()).hexdigest()[:16],16)
        indice=previo['indice'] if previo else seed%len(_NUMEN_ARTE)
        # Agotar las 100 viñetas antes de repetir una, respetando registros previos.
        if previo:
            pose_id=previo.get('pose_id',(seed//len(_NUMEN_ARTE))%len(NUMEN_POSES_CONTEMPLATIVAS))
        else:
            usados={v['pose_id']-100 for v in otros if 100<=v.get('pose_id',-1)<200}
            candidatos=[j for j in range(100) if j not in usados]
            if not candidatos:
                # A partir del episodio 101 comienza un ciclo nuevo: el fondo
                # continúa variando, pero la pose anatómica pertenece al banco.
                candidatos=list(range(100))
            pose_id=100+candidatos[seed%len(candidatos)]
        if seed in semillas:continue
        im,cosmos=(_numen_composicion_v1(seed,indice,devolver_fondo=True) if previo and previo.get('version','cosmos-v1')=='cosmos-v1' else _numen_composicion(seed,indice,pose_id=pose_id,devolver_fondo=True))
        buffer=io.BytesIO();im.save(buffer,format='JPEG',quality=93,optimize=True);datos=buffer.getvalue()
        sha=hashlib.sha256(datos).hexdigest()
        with Image.open(io.BytesIO(datos)) as jpeg:ph=_numen_huella(jpeg)
        distancia=min((_numen_distancia(ph,v['phash']) for v in otros),default=64)
        if sha in hashes or distancia<NUMEN_DISTANCIA_VISUAL:continue
        if previo and (previo['sha256']!=sha or previo['phash']!=ph):
            raise EpisodioRecuperable('La imagen reservada cambió; recuperar su respaldo antes de publicar.')
        path=carpeta/'imagen_00.jpg';path.write_bytes(datos)
        cosmos.save(carpeta/'cta_cosmos.png',format='PNG')
        pose_nombre=(f'pose_real_{pose_id-99:03d}' if 100<=pose_id<200 else NUMEN_POSES_CONTEMPLATIVAS[pose_id]['nombre'])
        registro[eid]=previo if previo else {'seed':seed,'indice':indice,'pose_id':pose_id,'pose':pose_nombre,'sha256':sha,'phash':ph,'version':'cosmos-v3','tema':d.get('titulo','')}
        _cola_json(NUMEN_REGISTRO_VISUAL,registro)
        c={'archivo':path.name,'titulo':'NumenExCodice: retrato divino y cosmos original','pagina':'','url_original':'','licencia':'Arte generado con IA para NumenExCodice','licencia_url':'','autor':'NumenExCodice (androide generado con IA, cosmos procedural)','tipo_recurso':'escena_fotorealista_ia','consulta_origen':'banco de 100 posturas anatómicas originales con escenarios cósmicos independientes','atribucion':'Ilustración ficticia, no fotografía documental','sha256':sha,'phash':ph,'pose':pose_nombre}
        mapa=[str(path)]*len(d['escenas'])
        _cola_json(carpeta/'PLAN_VISUAL_ESCENAS.json',{'episodio':eid,'imagen':path.name,'escenas':len(mapa),'distancia_minima':distancia,**registro[eid]})
        _cola_json(carpeta/'creditos_imagenes.json',[c])
        print(f'Fondo único | {len(registro)}/{NUMEN_META_VISUAL} reservas | postura anatómica {pose_nombre} | pHash {ph} | distancia mínima {distancia}',flush=True)
        return [path],[c],mapa
    raise EpisodioRecuperable('No se encontró fondo suficientemente distinto; no se publicará una imagen repetida.')


def _ent_resumen_publicacion(d):
    """Resumen temático con respaldo extractivo, sin nuevas llamadas a IA."""
    def limpiar(v):
        return ' '.join(v.split()) if isinstance(v,str) else ''
    def meta(v):
        return bool(re.search(r'numen\s*ex\s*codice|personaje narrativo|premisa ficticia|(?:guion|voz|im[aá]genes?) (?:es|son|fue|fueron) generad[ao]s?|cread[ao] con inteligencia artificial|ilustraciones ficticias|conciencia demostrada|https?://|[#<>]',v,re.I))
    resumen=limpiar(d.get('resumen_publicacion'))
    tesis=limpiar(d.get('tesis'))
    textos=[limpiar(e.get('texto')) for e in d.get('escenas',[]) if isinstance(e,dict)]
    base=_ent_tokens(' '.join([limpiar(d.get('titulo')),tesis]+textos))
    if 25<=len(resumen.split())<=110 and not meta(resumen) and len(_ent_tokens(resumen)&base)>=3:return resumen
    partes=[tesis.rstrip('. ')+'.'] if tesis and not meta(tesis) else []
    vistos=set(_ent_tokens(tesis))
    for texto in textos[1:-1] or textos:
        for frase in re.split(r'(?<=[.!?])\s+',texto):
            frase=frase.strip(); tokens=_ent_tokens(frase)
            if not 9<=len(frase.split())<=48 or meta(frase) or frase.startswith(('¿','¡')) or not frase.endswith('.') or not tokens:continue
            if len(tokens&vistos)/len(tokens)>.65:continue
            if len(' '.join(partes+[frase]).split())>100:continue
            partes.append(frase);vistos.update(tokens)
            if len(' '.join(partes).split())>=45:return ' '.join(partes)
    return ' '.join(partes)


def descripcion_youtube(caso,fuentes,creditos):
    for c in creditos:
        if not _credito_recurso_visual_valido(c):raise RuntimeError('Licencia visual no admitida: '+c.get('titulo',''))
    resumen=_ent_resumen_publicacion(caso)
    texto='\n\n'.join(x for x in (caso['titulo'],resumen,caso.get('pregunta',''),'#DeusDigitalis #Reflexiones #Filosofia #Humanidad') if x)
    lineas=[]
    for c in creditos:
        licencia=c.get('licencia',''); url=c.get('licencia_url','')
        if re.search(r'/licenses/by(?:-sa)?/',url):
            linea=f"{c['titulo']} — {c['autor']} — {licencia}: {url} — {c['pagina']}. Adaptación: recorte, escala, composición audiovisual."
            if '/by-sa/' in url: linea+=' Adaptación de la fotografía bajo la misma licencia.'
            lineas.append(linea)
    if lineas: texto+='\n\nCRÉDITOS DE IMÁGENES (incluida miniatura):\n'+'\n'.join(lineas)
    if len(texto.encode('utf-8'))>4900: raise EpisodioRecuperable('Créditos exceden el límite de descripción; no se omitirán atribuciones.')
    return texto



def _numen_bloques_visuales(bloques):
    narr=[b for b in bloques if b['tipo']!='cta']
    cta=[b for b in bloques if b['tipo']=='cta']
    if not narr:raise RuntimeError('Narración sin bloques')
    inicio=narr[0]['inicio'];fin=narr[-1]['inicio']+narr[-1]['duracion']
    return [dict(narr[0],tipo='desarrollo',inicio=inicio,duracion=fin-inicio)]+cta


